package pt.realmcouncil.domain;

import com.google.gson.JsonParser;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static pt.realmcouncil.domain.CouncilAdministration.*;

class CouncilAdministrationTest {
    static final UUID A=new UUID(1,1),B=new UUID(1,2);
    static final long NOW=1000000;
    private static Settings settings(){return new Settings(0,1,2,3,4,5,1,12,3);}
    private static CouncilState state(){var s=new CouncilState();s.observe(A,"Alice",2400,NOW-1);s.observe(B,"OfflineBob",0,NOW-1);settings().create(s,"Realm Governor",NOW);return s;}
    @Test void customRulesCreatePersistentElectionWithoutChangingTheDefaults(){var s=state();assertEquals(0,s.current.minimumPlayMinutes);assertEquals(NOW+60000,s.current.nominationEnd);assertEquals(NOW+360000,s.current.votingEnd);assertEquals(240000,s.current.termMillis);assertTrue(s.current.eligible.contains(B));var restored=CouncilState.fromJson(s.toJson());assertEquals(0,CouncilView.of(restored,A,new CouncilState.Identity("Alice","",0,false),false,"remote",NOW,120).minimumPlayMinutes());assertEquals(settings(),Settings.decode(CouncilState.JSON.toJson(settings())));}
    @Test void invalidSettingsAndMalformedInputsAreRejectedBeforeCreation(){for(String json:List.of("null","[]","not JSON","{}","{\"minimumPlayMinutes\":999999}","{\"nominationMinutes\":\"invalid\"}"))assertThrows(IllegalArgumentException.class,()->Settings.decode(json));assertThrows(IllegalArgumentException.class,()->new Settings(-1,1,1,1,1,1,1,1,1).validated());assertThrows(IllegalArgumentException.class,()->new Settings(0,0,1,1,1,1,1,1,1).validated());assertThrows(IllegalArgumentException.class,()->new Settings(0,1,1,1,1,525601,1,1,1).validated());assertThrows(IllegalArgumentException.class,()->new Settings(0,1,1,1,1,1,100001,1,1).validated());assertThrows(IllegalArgumentException.class,()->new Settings(0,1,1,1,1,1,1,17,1).validated());assertThrows(IllegalArgumentException.class,()->new Settings(0,1,1,1,1,1,1,1,11).validated());}
    @Test void operatorRollIsBoundedSearchableAndContainsOfflineCitizens(){var s=state();for(int i=0;i<1000;i++)s.observe(new UUID(8,i),"Citizen"+i,1200,NOW-1);var first=of(s,settings(),Set.of(A),"",0,NOW);assertEquals(1002,first.totalPlayers());assertEquals(PAGE_SIZE,first.players().size());assertEquals(0,of(s,settings(),Set.of(),"",-99,NOW).page());var last=of(s,settings(),Set.of(),"",Integer.MAX_VALUE,NOW);assertEquals(last.pages()-1,last.page());assertTrue(last.players().size()<=PAGE_SIZE);var bob=of(s,settings(),Set.of(A),"  offlineBOB  ",0,NOW);assertEquals(1,bob.totalPlayers());assertEquals(B,bob.players().getFirst().id());assertFalse(bob.players().getFirst().online());assertTrue(bob.players().getFirst().eligible());assertEquals(0,bob.players().getFirst().playMinutes());assertThrows(IllegalArgumentException.class,()->of(s,settings(),Set.of(),"x".repeat(33),0,NOW));}
    @Test void publicProjectionHasNoRollAndOperatorProjectionNeverIncludesBallots(){var s=state();s.nominate(A,new CouncilState.Identity("Alice","",0,false),"A good realm","sun","Build a public market.",NOW);s.advance(NOW);s.advance(NOW);s.cast(B,s.current.id,1,A,NOW);String publicJson=CouncilState.JSON.toJson(CouncilView.of(s,A,new CouncilState.Identity("Alice","",0,false),false,"remote",NOW,120));assertFalse(publicJson.contains(B.toString()));assertFalse(publicJson.contains("administration"));String admin=CouncilState.JSON.toJson(of(s,settings(),Set.of(),"",0,NOW));assertTrue(admin.contains(B.toString()));assertFalse(admin.contains("ballots"));assertFalse(admin.contains("voted"));assertFalse(admin.contains("choice"));}
    @Test void staleConfirmationCannotAdvanceAnotherPhaseOrElection(){var s=state();String id=s.current.id.toString();current(s,id,1,"NOMINATIONS");s.advance(NOW);assertThrows(IllegalArgumentException.class,()->current(s,id,1,"NOMINATIONS"));assertThrows(IllegalArgumentException.class,()->current(s,id,2,"CAMPAIGN"));assertThrows(IllegalArgumentException.class,()->current(s,UUID.randomUUID().toString(),1,"CAMPAIGN"));s.cancel(NOW);settings().create(s,"Another election",NOW);assertThrows(IllegalArgumentException.class,()->current(s,id,1,"CANCELLED"));current(new CouncilState(),"",0,"");}
    @Test void excludingAnElectorAlsoWithdrawsTheirCandidacyAndLocksAfterNominations(){var s=state();s.nominate(B,new CouncilState.Identity("Bob","",0,false),"A good realm","sun","Build a public market.",NOW);s.exclude(B);assertFalse(s.current.eligible.contains(B));assertFalse(s.current.candidates.containsKey(B));s.enrol(B);s.advance(NOW);assertThrows(IllegalArgumentException.class,()->s.exclude(B));assertTrue(s.current.eligible.contains(B));}
    @Test void savedVersion010IsReadableAndUsesTheConfiguredThresholdFallback(){var s=state();var json=JsonParser.parseString(s.toJson()).getAsJsonObject();json.getAsJsonObject("current").remove("minimumPlayMinutes");var restored=CouncilState.fromJson(json.toString());assertNull(restored.current.minimumPlayMinutes);assertEquals(120,CouncilView.of(restored,A,new CouncilState.Identity("Alice","",0,false),false,"remote",NOW,120).minimumPlayMinutes());}
}
